CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT 'Jogador' CHECK (char_length(display_name) BETWEEN 2 AND 50), avatar_url text, leaderboard_enabled boolean NOT NULL DEFAULT false, preferences jsonb NOT NULL DEFAULT '{}');
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile_read ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY own_profile_update ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE FUNCTION public.create_player_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES (NEW.id, left(coalesce(nullif(NEW.raw_user_meta_data->>'display_name',''),nullif(NEW.raw_user_meta_data->>'name',''),'Jogador'),50)); RETURN NEW; END $$;
CREATE TRIGGER respawn_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_player_profile();
CREATE TABLE public.player_library (user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE, game_name text NOT NULL CHECK(char_length(game_name) BETWEEN 1 AND 150), favorite boolean NOT NULL DEFAULT false, played_at timestamptz, PRIMARY KEY(user_id,game_name));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.player_library TO authenticated; GRANT ALL ON public.player_library TO service_role;
ALTER TABLE public.player_library ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_library ON public.player_library FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.game_ratings (user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE, game_name text NOT NULL CHECK(char_length(game_name) BETWEEN 1 AND 150), rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5), PRIMARY KEY(user_id,game_name));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.game_ratings TO authenticated; GRANT ALL ON public.game_ratings TO service_role;
ALTER TABLE public.game_ratings ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_ratings ON public.game_ratings FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.play_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE NOT NULL, game_name text NOT NULL CHECK(char_length(game_name) BETWEEN 1 AND 150), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.play_events TO authenticated; GRANT ALL ON public.play_events TO service_role;
ALTER TABLE public.play_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_plays_read ON public.play_events FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY own_plays_write ON public.play_events FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE INDEX plays_user_time ON public.play_events(user_id,created_at);
CREATE TABLE public.game_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE NOT NULL, title text NOT NULL CHECK(char_length(title) BETWEEN 2 AND 100), description text NOT NULL DEFAULT '' CHECK(char_length(description)<=500), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.game_requests TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.game_requests TO authenticated; GRANT ALL ON public.game_requests TO service_role;
ALTER TABLE public.game_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_requests ON public.game_requests FOR SELECT USING(true);
CREATE POLICY own_requests ON public.game_requests FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY own_requests_update ON public.game_requests FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE POLICY own_requests_delete ON public.game_requests FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.request_votes(request_id uuid REFERENCES public.game_requests(id) ON DELETE CASCADE, user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE, PRIMARY KEY(request_id,user_id));
GRANT SELECT,INSERT,DELETE ON public.request_votes TO authenticated; GRANT ALL ON public.request_votes TO service_role;
ALTER TABLE public.request_votes ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_vote_read ON public.request_votes FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY own_vote_insert ON public.request_votes FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY own_vote_delete ON public.request_votes FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.game_feedback(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE NOT NULL, game_name text NOT NULL, message text NOT NULL CHECK(char_length(message) BETWEEN 5 AND 1000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.game_feedback TO authenticated; GRANT ALL ON public.game_feedback TO service_role;
ALTER TABLE public.game_feedback ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_feedback_read ON public.game_feedback FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY own_feedback_insert ON public.game_feedback FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE FUNCTION public.community_summary() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('plays',coalesce((SELECT jsonb_agg(t) FROM (SELECT game_name,count(*) AS plays FROM play_events GROUP BY game_name ORDER BY count(*) DESC LIMIT 20)t),'[]'::jsonb),'ratings',coalesce((SELECT jsonb_agg(t) FROM (SELECT game_name,avg(rating) AS average,count(*) AS votes FROM game_ratings GROUP BY game_name ORDER BY avg(rating) DESC LIMIT 20)t),'[]'::jsonb),'players',coalesce((SELECT jsonb_agg(t) FROM (SELECT p.id,p.display_name,p.avatar_url,count(e.id) AS plays FROM profiles p LEFT JOIN play_events e ON e.user_id=p.id WHERE p.leaderboard_enabled GROUP BY p.id ORDER BY count(e.id) DESC LIMIT 20)t),'[]'::jsonb),'requests',coalesce((SELECT jsonb_agg(t) FROM (SELECT r.id,r.user_id,r.title,r.description,r.created_at,p.display_name,(SELECT count(*) FROM request_votes v WHERE v.request_id=r.id) AS votes FROM game_requests r JOIN profiles p ON p.id=r.user_id ORDER BY r.created_at DESC LIMIT 100)t),'[]'::jsonb)); $$;
REVOKE ALL ON FUNCTION public.community_summary() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.community_summary() TO anon,authenticated;
CREATE FUNCTION public.limit_player_plays() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM play_events WHERE user_id=NEW.user_id AND created_at>now()-interval '10 seconds') THEN RAISE EXCEPTION 'Aguarde antes de registrar outra partida'; END IF; RETURN NEW; END $$;
CREATE TRIGGER play_rate_limit BEFORE INSERT ON public.play_events FOR EACH ROW EXECUTE FUNCTION public.limit_player_plays();